# ---------------------------------------------------------------------------
# Helper to build a SHOT
# ---------------------------------------------------------------------------
def shot(shot_id, tech, lens_focal, ap, ss, iso, distance, bg_distance,
         composition, angle, height_m, pose, scene_notes,
         reasoning, dos, donts, day, afternoon, night,
         dog_subject, human_subject):
    # Field-card safety/clarity rules apply to every plan and every renderer.
    # Ghost = controlled human mover against a fixed scene; the dog stays out.
    # Long exposure around streets/traffic = no dog subject; prioritize tripod safety.
    if tech == "fantasma":
        dog_subject = {
            "pose": "walking_candid",
            "action": "Perro fuera de esta toma; usa una persona como sujeto móvil controlado."
        }
    elif tech == "larga_exp":
        dog_subject = {
            "pose": "sit_stay",
            "action": "Perro fuera de esta toma; prioriza trazas/escena y una posición protegida."
        }
    return {
        "id": shot_id,
        "technique": tech,
        "technique_label": TECHNIQUES[tech]["es"],
        "lens_focal": lens_focal,
        "aperture": ap,
        "shutter": ss,
        "iso": iso,
        "subject_distance_m": distance,
        "background_distance_m": bg_distance,
        "composition": composition,
        "composition_label": COMPOSITION_RULES[composition]["es"],
        "angle": angle,
        "angle_label": CAMERA_ANGLES[angle]["es"],
        "camera_height_m": height_m,
        "pose": pose,
        "scene_notes": scene_notes,
        "reasoning": reasoning,
        "dos": dos,
        "donts": donts,
        "settings_by_time": {"day": day, "afternoon": afternoon, "night": night},
        "subjects": {"dog": dog_subject, "human": human_subject},
    }


