PLANS = [PLAN_A, PLAN_B, PLAN_C, PLAN_D, PLAN_E, PLAN_F]

# ---------------------------------------------------------------------------
# Export to JSON helper (used by the export script)
# ---------------------------------------------------------------------------
def to_dict():
    return {
        "gear": GEAR,
        "composition_rules": COMPOSITION_RULES,
        "camera_angles": CAMERA_ANGLES,
        "techniques": TECHNIQUES,
        "poses_human": POSES_HUMAN,
        "poses_dog": POSES_DOG,
        "field_baselines": FIELD_BASELINES,
        "plans": PLANS,
    }


if __name__ == "__main__":
    import json
    from pathlib import Path
    root = Path(__file__).resolve().parents[1]
    out = root / "data" / "plans.json"
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(json.dumps(to_dict(), ensure_ascii=False, indent=2), encoding="utf-8")
    n = sum(len(p["shots"]) for p in PLANS)
    print(f"✓ Wrote {out} ({n} shots across {len(PLANS)} plans)")
